# ============================================================
#  Deploy GitHub Actions Workflow to Target Repo
#  Pushes the auto-generated enforce-workflow-rules.yml
#  to .github/workflows/ in the target GitHub repo
#  Phase: 02-prep
# ============================================================

[CmdletBinding()]
param(
    [string]$ConfigPath = "$PSScriptRoot\..\config\boards-migration-config.json"
)

$ErrorActionPreference = "Stop"
$scriptRoot = Split-Path $PSScriptRoot -Parent

. "$scriptRoot\helpers\logging.ps1"
. "$scriptRoot\helpers\github-helpers.ps1"

$config = Read-JsonConfig -Path $ConfigPath
$ghOrg  = $config.target.organization
$ghRepo = $config.target.repository
$ghPat  = if ($config.target.pat -match '^\$\(') { $env:GH_PAT } else { $config.target.pat }
$reportDir = Join-Path $scriptRoot $config.output.reportDir
$logDir = Join-Path $scriptRoot $config.output.logDir

Initialize-Log -LogPath (Join-Path $logDir "deploy-workflow-$(Get-Date -Format 'yyyyMMdd-HHmmss').log")

Write-LogSection "Deploy GitHub Actions Workflow"

$workflowSource = Join-Path $reportDir "github-workflows" "enforce-workflow-rules.yml"

if (-not (Test-Path $workflowSource)) {
    Write-Log -Message "Workflow file not found: $workflowSource. Run discover phase first." -Level "WARN"
    Write-Log -Message "Skipping workflow deployment." -Level "WARN"
    exit 0
}

$workflowContent = Get-Content $workflowSource -Raw
$base64Content = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($workflowContent))

$targetPath = ".github/workflows/enforce-workflow-rules.yml"
$headers = @{
    Authorization = "token $ghPat"
    Accept = "application/vnd.github.v3+json"
}

Write-Log -Message "Deploying workflow to $ghOrg/$ghRepo/$targetPath" -Level "INFO"

# Check if file already exists (need SHA for update)
$existingSha = $null
try {
    $existingFile = Invoke-RestMethod -Uri "https://api.github.com/repos/$ghOrg/$ghRepo/contents/$targetPath" `
        -Headers $headers -Method Get -ErrorAction SilentlyContinue
    $existingSha = $existingFile.sha
    Write-Log -Message "Existing workflow found (SHA: $existingSha) - will update" -Level "INFO"
} catch {
    Write-Log -Message "No existing workflow - will create new" -Level "INFO"
}

# Create or update the file
$body = @{
    message = "chore: deploy ADO workflow enforcement rules (auto-generated by migration pipeline)"
    content = $base64Content
    branch = "main"
}

if ($existingSha) {
    $body.sha = $existingSha
}

try {
    $result = Invoke-RestMethod -Uri "https://api.github.com/repos/$ghOrg/$ghRepo/contents/$targetPath" `
        -Headers $headers -Method Put -Body ($body | ConvertTo-Json) -ContentType "application/json"
    
    Write-Log -Message "Workflow deployed successfully!" -Level "SUCCESS"
    Write-Log -Message "  Commit: $($result.commit.sha)" -Level "INFO"
    Write-Log -Message "  URL: $($result.content.html_url)" -Level "INFO"
} catch {
    Write-Log -Message "Failed to deploy workflow: $($_.Exception.Message)" -Level "ERROR"
    Write-Log -Message "You can manually copy the file from: $workflowSource" -Level "WARN"
    Write-Log -Message "To: .github/workflows/enforce-workflow-rules.yml in your GitHub repo" -Level "WARN"
}

Write-Log -Message "Workflow deployment complete." -Level "SUCCESS"
